SELECT CURRENT_TIMESTAMP() checked_at_utc,'Motor change' route,PaymentMethod,PaymentChannel,COUNT(*) row_count FROM `pacific-plating-282708.sap_view.RCB_Motor_process_3_change` GROUP BY PaymentMethod,PaymentChannel UNION ALL SELECT CURRENT_TIMESTAMP(),'NonMotor change',PaymentMethod,PaymentChannel,COUNT(*) FROM `pacific-plating-282708.sap_view.RCB_NonMotor_process_2_cancel` GROUP BY PaymentMethod,PaymentChannel UNION ALL SELECT CURRENT_TIMESTAMP(),'Motor create',PaymentMethod,PaymentChannel,COUNT(*) FROM `pacific-plating-282708.sap_view.RCB_Motor_process_create` GROUP BY PaymentMethod,PaymentChannel UNION ALL SELECT CURRENT_TIMESTAMP(),'NonMotor create',PaymentMethod,PaymentChannel,COUNT(*) FROM `pacific-plating-282708.sap_view.RCB_NonMotor_process_1_create` GROUP BY PaymentMethod,PaymentChannel;